def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return: dict with days, seconds, microseconds or None
    """
    # Allow None to be dehydrated to None
    if value is None:
        return None

    # Basic type check: ensure it's a datetime.timedelta instance
    # We avoid importing datetime by checking the type's name and module
    t_type = type(value)
    if not (t_type.__name__ == 'timedelta' and t_type.__module__ == 'datetime'):
        raise TypeError(f"Expected datetime.timedelta, got {type(value).__name__}")

    # Dehydrate into a serializable dictionary
    try:
        return {
            'days': value.days,
            'seconds': value.seconds,
            'microseconds': value.microseconds
        }
    except Exception as exc:
        raise ValueError(f"Failed to dehydrate timedelta: {exc}") from exc

