def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return: ISO 8601 string representation of the time
    """
    if value is None:
        return None
    # Basic type check: ensure the object behaves like a datetime.time
    if not hasattr(value, "isoformat") or not hasattr(value, "hour"):
        raise TypeError(f"Expected a datetime.time instance, got {type(value).__name__}")
    try:
        return value.isoformat()
    except Exception as exc:
        raise TypeError(f"Failed to dehydrate time value {value!r}: {exc}") from exc

