def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    # Attempt to retrieve keys from common internal mapping attributes
    for attr in ("_data", "data"):
        if hasattr(self, attr):
            mapping = getattr(self, attr)
            if hasattr(mapping, "keys") and callable(mapping.keys):
                try:
                    return list(mapping.keys())
                except Exception as exc:
                    raise TypeError(f"Failed to retrieve keys from {attr}: {exc}") from exc
    # If the instance itself behaves like a dict (or dict subclass)
    if isinstance(self, dict):
        try:
            return list(self.keys())
        except Exception as exc:
            raise TypeError(f"Failed to retrieve keys from dict: {exc}") from exc
    # No suitable mapping found
    raise TypeError("Record does not support key retrieval")

