def unit_of_work(metadata=None, timeout=None):
    """
    Decorator for transaction functions that allows extra control over how the transaction is carried out.
    """
    def decorator(func):
        def wrapper(session, *args, **kwargs):
            # Validate metadata
            if metadata is not None and not isinstance(metadata, dict):
                raise TypeError("metadata must be a dict or None")
            # Validate timeout
            if timeout is not None:
                if not isinstance(timeout, (int, float)):
                    raise TypeError("timeout must be a float or None")
                if timeout < 0:
                    raise ValueError("timeout must not be negative")
            # Ensure session has write_transaction method
            if not hasattr(session, "write_transaction"):
                raise TypeError("session must have a write_transaction method")
            # Execute the transaction function
            return session.write_transaction(func, *args, **kwargs)
        return wrapper
    return decorator

