def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Attempt to obtain items in order
    try:
        items = list(self.items())
    except AttributeError:
        # Fallback: treat self as a list/tuple of (key, value) pairs
        if isinstance(self, (list, tuple)):
            items = list(self)
        else:
            raise TypeError("Object does not support items() or list of tuples")
    # If no keys specified, return all values
    if not keys:
        return [v for _, v in items]
    result = []
    for key in keys:
        if isinstance(key, int):
            idx = key
            if idx < 0:
                idx += len(items)
            if idx < 0 or idx >= len(items):
                raise IndexError(f"Index {key} out of range")
            result.append(items[idx][1])
        else:
            for k, v in items:
                if k == key:
                    result.append(v)
                    break
            else:
                raise KeyError(f"Key {key} not found")
    return result

