def pop_u16(self):
    """Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    # Determine the data container
    data = getattr(self, 'data', None)
    if data is None:
        data = getattr(self, '_data', None)
    if data is None:
        raise AttributeError("Object has no 'data' or '_data' attribute")
    if len(data) < 2:
        raise ValueError("Not enough bytes to pop u16")
    try:
        low = data.pop()
        high = data.pop()
    except Exception as exc:
        raise TypeError("Data container does not support pop operation") from exc
    # Ensure we have integers in the 0-255 range
    if not isinstance(low, int) or not isinstance(high, int):
        try:
            low = int(low)
            high = int(high)
        except Exception as exc:
            raise TypeError("Popped values must be integers") from exc
    return (high << 8) | low

