                raise TypeError(f"hydration_hooks keys must be types, got {type(key).__name__}")
            if not callable(val):
                raise TypeError(f"hydration_hooks values must be callable, got {type(val).__name__}")

    # Validate handlers
    for name, func in handlers.items():
        if not callable(func):
            raise TypeError(f"handler '{name}' must be callable, got {type(func).__name__}")

    # Construct the DISCARD message
    message = ('DISCARD', n, qid)

    # Append to the output queue
    try:
        self._output_queue.append(message)
    except AttributeError:
