def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    try:
        if key in self:
            return self[key]
    except TypeError as e:
        # key is not hashable
        raise TypeError(f"unhashable type: {type(key).__name__}") from e
    except Exception:
        # propagate any other exception that may arise from __contains__
        raise
    # key not present, set it to default
    self[key] = default
    return default

