def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments.

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    # Prepare the output list
    if output is None:
        output = []
    else:
        if not isinstance(output, list):
            raise TypeError("output must be a list or None")

    # Helper to determine if an object should be treated as a single item
    def _is_single(item):
        return not isinstance(item, (list, tuple, set)) or isinstance(item, (str, bytes))

    # If the sequence itself is not iterable or is a string/bytes, treat it as a single item
    if sequence is None:
        raise TypeError("sequence cannot be None")
    if _is_single(sequence):
        output.append(sequence)
        return output

    # Iterate over the sequence and recursively normalize nested sequences
    for item in sequence:
        if _is_single(item):
            output.append(item)
        else:
            # Recursively flatten nested sequences
            _normalizeargs(item, output)

    return output

