def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Validate that inputs are not None
    if bins is None or edges is None:
        raise ValueError("bins and edges must not be None")

    # Convert to lists to allow multiple passes and length checks
    try:
        bins_list = list(bins)
    except TypeError:
        raise TypeError("bins must be an iterable of numbers")

    try:
        edges_list = list(edges)
    except TypeError:
        raise TypeError("edges must be an iterable of numbers")

    # Empty bins: integral is zero, but edges must still be of length 1
    if len(bins_list) == 0:
        if len(edges_list) != 1:
            raise ValueError("edges length must be 1 when bins is empty")
        return 0.0

    # Check that edges length matches bins length + 1
    if len(edges_list) != len(bins_list) + 1:
        raise ValueError("edges length must be len(bins) + 1")

    # Ensure all elements are numeric
    for i, val in enumerate(bins_list):
        if not isinstance(val, (int, float)):
            raise TypeError(f"bins[{i}] is not a number")
    for i, val in enumerate(edges_list):
        if not isinstance(val, (int, float)):
            raise TypeError(f"edges[{i}] is not a number")

    # Ensure edges are non-decreasing
    for i in range(len(edges_list) - 1):
        if edges_list[i + 1] < edges_list[i]:
            raise ValueError("edges must be non-decreasing")

    # Compute bin widths
    widths = [edges_list[i + 1] - edges_list[i] for i in range(len(edges_list) - 1)]

    # Compute integral as sum of bin value times width
    integral_value = sum(b * w for b, w in zip(bins_list, widths))

    return float(integral_value)

