        raise TypeError("last_applied_manifest must be a list")
    if not isinstance(observer_schema, list):
        raise TypeError("observer_schema must be a list")
    if not isinstance(response, list):
        raise TypeError("response must be a list")

    # If response is empty, nothing to do
    if not response:
        return last_applied_manifest

    # Ensure last_applied_manifest has at least as many elements as response
    for i, resp_item in enumerate(response):
        # Extend the list if necessary
        if i >= len(last_applied_manifest):
            # Default placeholder; will be replaced below
            last_applied_manifest.append(None)

        current_item = last_applied_manifest[i]

        # Handle dict items
        if isinstance(resp_item, dict):
            if not isinstance(current_item, dict):
                current_item = {}
                last_applied_manifest[i] = current_item
            # Recursively update the dict
