        if isinstance(resp_item, list):
            if not isinstance(current_item, list):
                current_item = []
                last_applied_manifest[i] = current_item
            # Recursively update the nested list
            try:
                update_last_applied_manifest_list_from_resp(
                    current_item, observer_schema, resp_item
                )
            except Exception as exc:
                raise RuntimeError(
                    f"Failed to update nested list at index {i} of list: {exc}"
                ) from exc
            continue

        # Handle primitive values (int, str, bool, None, etc.)
        # If the current item is None or of a different type, replace it.
        if current_item is None or not isinstance(current_item, type(resp_item)):
            last_applied_manifest[i] = resp_item

    return last_applied_manifest

