def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type checks
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if not isinstance(extract_spec_version, bool):
        raise TypeError("extract_spec_version must be a boolean")

    # Default spec_version if not already set
    if not hasattr(self, "spec_version") or self.spec_version is None:
        self.spec_version = "1.0"

    # Mapping of spec_version to required keys
    spec_requirements = {
        "1.0": {"name", "items"},
        "2.0": {"id", "entries"},
        "3.0": {"uuid", "components"},
    }

    # Extract spec_version from inventory if requested
    if extract_spec_version:
        inv_type = inventory.get("type")
        if isinstance(inv_type, str) and inv_type in spec_requirements:
            self.spec_version = inv_type

    # Validate against the current spec_version
    required_keys = spec_requirements.get(self.spec_version)
    if required_keys is None:
        raise ValueError(f"Unsupported spec_version '{self.spec_version}'")

    missing = required_keys - inventory.keys()
    if missing:
        raise ValueError(f"Inventory missing required keys for spec_version '{self.spec_version}': {sorted(missing)}")

    # Additional generic checks (example: ensure 'items' is a list if present)
    if "items" in inventory and not isinstance(inventory["items"], list):
        raise ValueError("The 'items' key must be a list")
    if "entries" in inventory and not isinstance(inventory["entries"], list):
        raise ValueError("The 'entries' key must be a list")
    if "components" in inventory and not isinstance(inventory["components"], list):
        raise ValueError("The 'components' key must be a list")

    return True

