def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate inputs
    if not isinstance(inventory, (list, tuple)):
        raise TypeError("inventory must be a list or tuple of file entries")
    if not isinstance(version, (int, float)):
        raise TypeError("version must be a numeric type")

    path_map = {}
    for entry in inventory:
        # Each entry is expected to be a mapping with required keys
        if not isinstance(entry, dict):
            raise TypeError("each inventory entry must be a dict")
        try:
            logical_path = entry["logical_path"]
            content_file = entry["content_file"]
            entry_version = entry["version"]
        except KeyError as exc:
            raise KeyError(f"inventory entry missing required key: {exc}") from None

        # Only consider entries that match the requested version
        if entry_version != version:
            continue

        # Add the content file to the set for this logical path
        path_map.setdefault(logical_path, set()).add(content_file)

    return path_map

