def files_list(path):
    """
    Return the files in `path`
    """
    import os
    # Validate path type
    try:
        path = os.fspath(path)
    except Exception as exc:
        raise TypeError("path must be a string or path-like object") from exc

    # Check existence
    if not os.path.exists(path):
        raise FileNotFoundError(f"No such file or directory: '{path}'")

    # Check that it's a directory
    if not os.path.isdir(path):
        raise NotADirectoryError(f"Not a directory: '{path}'")

    try:
        # Use scandir for efficient iteration
        files = [entry.name for entry in os.scandir(path) if entry.is_file()]
    except PermissionError as exc:
        raise PermissionError(f"Permission denied: '{path}'") from exc
    except OSError as exc:
        # Re-raise other OS errors
        raise exc

    return files

