def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os

    # Validate input
    if not isinstance(folder, str):
        raise TypeError(f"folder must be a string, got {type(folder).__name__}")
    if not os.path.exists(folder):
        raise FileNotFoundError(f"Folder does not exist: {folder}")
    if not os.path.isdir(folder):
        raise NotADirectoryError(f"Path is not a directory: {folder}")

    # Find all XML files and collect their basenames
    xml_basenames = set()
    try:
        for root, _, files in os.walk(folder):
            for fname in files:
                if fname.lower().endswith('.xml'):
                    basename = os.path.splitext(fname)[0]
                    xml_basenames.add(basename)
    except Exception as exc:
        raise RuntimeError(f"Error while scanning for XML files in {folder}: {exc}") from exc

    # If no XML files found, return empty dict
    if not xml_basenames:
        return {}

    # Group all files that share a basename with an XML file
    groups = {}
    try:
        for root, _, files in os.walk(folder):
            for fname in files:
                basename = os.path.splitext(fname)[0]
                if basename in xml_basenames:
                    full_path = os.path.join(root, fname)
                    groups.setdefault(basename, []).append(full_path)
    except Exception as exc:
        raise RuntimeError(f"Error while grouping files in {folder}: {exc}") from exc

    return groups

