        if _func_name(e) == 'And' and _args(e) and len(_args(e)) == 2:
            left_e, right_e = _args(e)
            if _func_name(f) == 'And' and _args(f) and len(_args(f)) == 2:
                left_f, right_f = _args(f)
                if left_e == left_f:
                    if _func_name(right_e) == 'Or' and _args(right_e) and len(_args(right_e)) == 2:
                        # right_e should be (~A | B)
                        not_a = None
                        B = None
                        for arg in _args(right_e):
                            if _is_not(arg, left_e):
                                not_a = arg
                            else:
                                B = arg
                        if not_a is not None and B is not None:
                            if right_f == B:
                                return True
        # e = A | (~A & B), f = A | B
        if _func_name(e) == 'Or' and _args(e) and len(_args(e)) == 2:
            left_e, right_e = _args(e)
            if _func_name(f) == 'Or' and _args(f) and len(_args(f)) == 2:
