                        B = None
                        for arg in _args(right_e):
                            if _is_not(arg, left_e):
                                not_a = arg
                            else:
                                B = arg
                        if not_a is not None and B is not None:
                            if right_f == B:
                                return True
        return False

    def _absorbs(e, f):
        """Return True if e absorbs f."""
        return _is_absorption(e, f) or _is_negative_absorption(e, f)

    # Main logic: iterate over pairs and remove absorbed expressions
    exprs = list(args)
    to_remove = set()
    n = len(exprs)
    for i in range(n):
        if i in to_remove:
            continue
        for j in range(i + 1, n):
