def get_versions():
    """Get version information or return default if unable to do so."""
    # Try to get version from environment variable
    import os
    env_version = os.getenv("VERSION")
    if env_version:
        return env_version.strip()

    # Try to read a VERSION file in the current directory
    try:
        with open("VERSION", "r", encoding="utf-8") as f:
            line = f.readline()
            if line:
                return line.strip()
    except FileNotFoundError:
        pass
    except Exception:
        pass

    # Try to get the latest git tag
    try:
        import subprocess
        # Use --tags to list tags, --abbrev=0 to get the most recent tag
        result = subprocess.run(
            ["git", "describe", "--tags", "--abbrev=0"],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=True,
        )
        git_version = result.stdout.strip()
        if git_version:
            return git_version
    except (subprocess.CalledProcessError, FileNotFoundError, Exception):
        pass

    # Try to get version from importlib.metadata (Python 3.8+)
    try:
        import importlib.metadata
        # Attempt to get the version of the current package if __package__ is set
        pkg_name = __package__
        if pkg_name:
            try:
                return importlib.metadata.version(pkg_name).strip()
            except importlib.metadata.PackageNotFoundError:
                pass
        # Fallback: try to get the version of the top-level package by inspecting the file path
        # This is a heuristic and may not work in all cases
        import sys
        if sys.modules.get(__name__):
            module = sys.modules[__name__]
            if hasattr(module, "__file__"):
                # Guess package name from file path
                path_parts = os.path.abspath(module.__file__).split(os.sep)
                if len(path_parts) >= 2:
                    guessed_pkg = path_parts[-2]
                    try:
                        return importlib.metadata.version(guessed_pkg).strip()
                    except importlib.metadata.PackageNotFoundError:
                        pass
    except Exception:
        pass

    # Default fallback
    return "0.0.0"

