def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate pieces
    if pieces is None:
        raise TypeError("pieces must be an iterable")
    if isinstance(pieces, (str, bytes)):
        raise TypeError("pieces must be an iterable of items, not a string")
    try:
        iterator = iter(pieces)
    except TypeError:
        raise TypeError("pieces must be an iterable")
    pieces_list = list(pieces)

    # Validate style
    if not isinstance(style, str):
        raise TypeError("style must be a string")
    style = style.lower()

    # Helper functions for rendering
    def join_with(sep):
        return sep.join(str(x) for x in pieces_list)

    def json_repr():
        return '[' + ', '.join(repr(x) for x in pieces_list) + ']'

    def tuple_repr():
        return str(tuple(pieces_list))

    def list_repr():
        return str(list(pieces_list))

    def string_repr():
        return ' '.join(str(x) for x in pieces_list)

    # Mapping of supported styles
    style_map = {
        'dot': lambda: join_with('.'),
        'dash': lambda: join_with('-'),
        'underscore': lambda: join_with('_'),
        'json': json_repr,
        'tuple': tuple_repr,
        'list': list_repr,
        'string': string_repr,
        'semver': lambda: join_with('.'),
    }

    if style not in style_map:
        raise ValueError(f"Unsupported style: {style}")

    return style_map[style]()

