def register_vcs_handler(vcs, method=None):
    """
    Create decorator to mark a method as the handler of a VCS.

    This function can be used as a decorator factory:

        @register_vcs_handler('git')
        def handle_git(...):
            ...

    It stores the provided method in a global registry keyed by the VCS name.
