def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """
        Validate storage root hierarchy.

        Parameters
        ----------
        validate_objects : bool, optional
            If True, each object will be validated using its ``validate`` or ``is_valid`` method.
        check_digests : bool, optional
            If True, each object will have its digest checked using its ``check_digest`` method.
        show_warnings : bool, optional
            If True, warnings will be printed for objects that fail validation or digest checks.

        Returns
        -------
        tuple
            (num_objects, good_objects) where
            - num_objects is the total number of objects processed,
            - good_objects is the number of objects that passed all requested checks.
        """
        # Validate input types
        if not isinstance(validate_objects, bool):
            raise TypeError("validate_objects must be a boolean")
        if not isinstance(check_digests, bool):
            raise TypeError("check_digests must be a boolean")
        if not isinstance(show_warnings, bool):
            raise TypeError("show_warnings must be a boolean")

        # Attempt to retrieve the iterable of objects from the storage root
        try:
            objects = self.get_objects()
        except AttributeError as exc:
            raise AttributeError("The object does not provide a 'get_objects' method") from exc
        except Exception as exc:
            raise RuntimeError("Failed to retrieve objects from the storage root") from exc

        # Ensure we have an iterable
        try:
            iterator = iter(objects)
        except TypeError as exc:
            raise TypeError("The result of get_objects() is not iterable") from exc

        num_objects = 0
        good_objects = 0

        for obj in iterator:
            num_objects += 1
            is_valid = True

            # Validate the object if requested
            if validate_objects:
                try:
                    # Prefer a 'validate' method; fall back to 'is_valid'
                    if hasattr(obj, "validate") and callable(obj.validate):
                        is_valid = obj.validate()
                    elif hasattr(obj, "is_valid") and callable(obj.is_valid):
                        is_valid = obj.is_valid()
                    else:
                        # If no validation method, assume valid
                        is_valid = True
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Validation failed for object {obj!r} with error: {exc}")

            # Check digest if requested
            if is_valid and check_digests:
                try:
                    if hasattr(obj, "check_digest") and callable(obj.check_digest):
                        digest_ok = obj.check_digest()
                    else:
                        # If no digest method, assume digest is ok
                        digest_ok = True
                except Exception as exc:
                    digest_ok = False
                    if show_warnings:
                        print(f"Warning: Digest check failed for object {obj!r} with error: {exc}")

                if not digest_ok:
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Digest check failed for object {obj!r}")

            if is_valid:
                good_objects += 1

        return num_objects, good_objects

