def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    # Helper to determine if a node is a MappingNode
    def is_mapping_node(node):
        return hasattr(node, 'tag') and node.tag == 'tag:yaml.org,2002:map'

    # Recursive merge of two nodes
    def merge_nodes(a, b):
        if is_mapping_node(a) and is_mapping_node(b):
            return merge_mapping_nodes(a, b)
        # For non-mapping nodes, the last value wins
        return b

    # Merge two MappingNodes by merging their value lists
    def merge_mapping_nodes(node1, node2):
        # Build a lookup for existing keys in node1
        mapping1 = {k.value: i for i, (k, v) in enumerate(node1.value)}
        for k2, v2 in node2.value:
            key_val = k2.value
            if key_val in mapping1:
                idx = mapping1[key_val]
                v1 = node1.value[idx][1]
                merged = merge_nodes(v1, v2)
                node1.value[idx] = (k2, merged)
            else:
                node1.value.append((k2, v2))
        return node1

    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list')
    result = []
    key_index = {}
    for item in nodes:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError('each item in nodes must be a tuple of (key_node, value_node)')
        key_node, value_node = item
        if not hasattr(key_node, 'value'):
            raise TypeError('key_node must have a value attribute')
        key_val = key_node.value
        if key_val not in key_index:
            result.append((key_node, value_node))
            key_index[key_val] = len(result) - 1
        else:
            idx = key_index[key_val]
            existing_key, existing_value = result[idx]
            merged_value = merge_nodes(existing_value, value_node)
            result[idx] = (existing_key, merged_value)
    return result

