def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse

    def _to_namespace(arg_list):
        """Convert a list of arguments into an argparse.Namespace."""
        attrs = {}
        i = 0
        while i < len(arg_list):
            token = arg_list[i]
            if token == '--':
                # End of options; treat remaining as positional (ignored here)
                break
            if token.startswith('--'):
                # Long option
                if '=' in token:
                    key, val = token[2:].split('=', 1)
                else:
                    key = token[2:]
                    # Look ahead for a value
                    if i + 1 < len(arg_list) and not arg_list[i + 1].startswith('-'):
                        val = arg_list[i + 1]
                        i += 1
                    else:
                        val = True
                attrs[key.replace('-', '_')] = val
            elif token.startswith('-') and len(token) > 1:
                # Short option; treat as flag
                key = token[1:]
                attrs[key.replace('-', '_')] = True
            else:
                # Positional argument; ignore for namespace
                pass
            i += 1
        return argparse.Namespace(**attrs)

    args = list(unparsed_arguments)
    subparser_name = None
    subparser_args = []
    global_args = []

    # Find first non-option token as subparser name
    for idx, token in enumerate(args):
        if token.startswith('-'):
            continue
        if token == '--':
            continue
        subparser_name = token
        subparser_args = args[idx + 1 :]
        global_args = args[:idx]
        break

    if subparser_name is None:
        # No subparser detected
        global_ns = _to_namespace(args)
        return {"global": global_ns}

    # Parse global and subparser arguments
    global_ns = _to_namespace(global_args)
    subparser_ns = _to_namespace(subparser_args)

    return {"global": global_ns, subparser_name: subparser_ns}

