    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to determine if a node is a MappingNode
    def is_mapping_node(node):
        try:
            return getattr(node, 'tag', None) == 'tag:yaml.org,2002:map' and hasattr(node, 'value') and isinstance(node.value, list)
        except Exception:
            return False

    # Merge two MappingNodes recursively
    def merge_mapping_nodes(node1, node2):
        if not is_mapping_node(node1) or not is_mapping_node(node2):
            # If either is not a mapping, last wins
            return node2
        # Build a dict for node1's entries preserving order
        merged_entries = []
        key_to_index = {}
        for idx, (k, v) in enumerate(node1.value):
            key_val = getattr(k, 'value', None)
            merged_entries.append((k, v))
            key_to_index[key_val] = idx
        # Merge node2 entries
        for k2, v2 in node2.value:
            key_val2 = getattr(k2, 'value', None)
            if key_val2 in key_to_index:
                idx = key_to_index[key_val2]
                _, existing_v = merged_entries[idx]
                if is_mapping_node(existing_v) and is_mapping_node(v2):
                    merged_v = merge_mapping_nodes(existing_v, v2)
                else:
                    merged_v = v2
                merged_entries[idx] = (k2, merged_v)
            else:
                merged_entries.append((k2, v2))
                key_to_index[key_val2] = len(merged_entries) - 1
        # Construct a new MappingNode with the same tag as node1
        try:
            return type(node1)(node1.tag, merged_entries)
        except Exception:
            # Fallback: modify node1 in place
            node1.value = merged_entries
            return node1

    result = []
    key_to_index = {}
    for key, value in nodes:
        key_val = getattr(key, 'value', None)
        if key_val in key_to_index:
            idx = key_to_index[key_val]
            _, existing_value = result[idx]
            if is_mapping_node(existing_value) and is_mapping_node(value):
                merged_value = merge_mapping_nodes(existing_value, value)
                result[idx] = (key, merged_value)
            else:
                # Last wins
                result[idx] = (key, value)
        else:
            result.append((key, value))
            key_to_index[key_val] = len(result) - 1
    return result

