def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError("dicts must be an iterable of dictionaries")
    # Reject plain dicts to avoid treating them as an iterable of keys
    if isinstance(dicts, dict):
        raise TypeError("dicts must be an iterable of dictionaries, not a single dictionary")
    try:
        iterator = iter(dicts)
    except TypeError as exc:
        raise TypeError("dicts must be an iterable of dictionaries") from exc

    result = {}
