    if commands is None:
        raise ValueError("commands must not be None")
    if isinstance(commands, str):
        import shlex
        cmd = shlex.split(commands)
    elif isinstance(commands, (list, tuple)):
        cmd = list(commands)
    else:
        raise TypeError("commands must be a string or a list/tuple of strings")
    if not cmd:
        raise ValueError("commands must not be empty")
    if args:
        if not isinstance(args, (list, tuple)):
            raise TypeError("args must be a list or tuple of strings")
        cmd.extend(args)
    # Configure stderr handling
    stderr = subprocess.DEVNULL if hide_stderr else subprocess.PIPE
    # Execute the command
    try:
        if verbose:
            print(f"Running command: {' '.join(cmd)}")
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr,
            check=True,
            text=True
        )
        if verbose:
            print(f"Command output:\n{result.stdout}")
            if not hide_stderr and result.stderr:
                print(f"Command stderr:\n{result.stderr}")
        return result
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command failed with return code {e.returncode}")
            if e.stdout:
                print(f"stdout:\n{e.stdout}")
            if e.stderr:
                print(f"stderr:\n{e.stderr}")
        raise
    except Exception as exc:
        if verbose:
            print(f"An error occurred while running the command: {exc}")
        raise

