    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    if request is None:
        raise ValueError("request cannot be None")

    # Helper to safely get attribute
    def _get_attr(obj, name, default=None):
        try:
            return getattr(obj, name, default)
        except Exception:
            return default

    # Check for public message header
    headers = _get_attr(request, "headers", {})
    if isinstance(headers, dict):
        try:
            if headers.get("X-Diaspora-Message-Type") == "public":
                return True
        except Exception:
            pass

    # Check for private message header
    if isinstance(headers, dict):
        try:
            if headers.get("X-Diaspora-Message-Type") == "private":
                return True
        except Exception:
            pass

    # Check for legacy payload in JSON body
    json_body = _get_attr(request, "json", None)
    if json_body is None and isinstance(request, dict):
        json_body = request
    if isinstance(json_body, dict):
        try:
            if json_body.get("legacy") is True:
                return True
            if json_body.get("diaspora") is not None:
                return True
        except Exception:
            pass

    # Check for query parameters
    args = _get_attr(request, "args", {})
    if isinstance(args, dict):
        try:
            if args.get("diaspora") is not None:
                return True
        except Exception:
            pass

    # Check for form data
    form = _get_attr(request, "form", {})
    if isinstance(form, dict):
        try:
            if form.get("diaspora") is not None:
                return True
        except Exception:
            pass

    return False

