def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    import urllib.request
    import urllib.parse
    from urllib.error import URLError, HTTPError

    if not isinstance(handle, str) or '@' not in handle:
        return None

    try:
        # Extract domain part
        _, domain = handle.split('@', 1)
        if not domain:
            return None

        # Build the webfinger URL
        resource = f"acct:{handle}"
        query = urllib.parse.urlencode({"resource": resource})
        url = f"https://{domain}/.well-known/webfinger?{query}"

        # Prepare request with appropriate headers
        req = urllib.request.Request(
            url,
            headers={"Accept": "application/jrd+json, application/json"},
            method="GET",
        )

        with urllib.request.urlopen(req, timeout=5) as resp:
            if resp.status != 200:
                return None
            content = resp.read()
            # Decode assuming UTF-8; fallback to ISO-8859-1 if needed
            try:
                return content.decode("utf-8")
            except UnicodeDecodeError:
                return content.decode("iso-8859-1")
    except (URLError, HTTPError, ValueError, Exception):
        # Any error (network, parsing, etc.) results in None
        return None

