def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    # Validate the handle
    if not isinstance(handle, str) or not handle.strip():
        raise ValueError("Handle must be a non-empty string")
    handle = handle.strip()
    # Remove optional 'acct:' prefix
    if handle.lower().startswith("acct:"):
        handle = handle[5:]
    if "@" not in handle:
        raise ValueError("Handle must contain '@' separating user and domain")
    user, domain = handle.rsplit("@", 1)
    if not user or not domain:
        raise ValueError("Handle must contain both user and domain parts")
    # Build the webfinger URL
    url = f"https://{domain}/.well-known/webfinger?resource=acct:{handle}"
    try:
        import requests
    except ImportError as exc:
        raise RuntimeError("The 'requests' library is required to retrieve webfinger documents") from exc
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve webfinger document from {url}: {exc}") from exc
    try:
        data = response.json()
    except Exception as exc:
        raise ValueError(f"Failed to parse JSON from webfinger document: {exc}") from exc
    return data

