def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    import os
    import fnmatch

    if not isinstance(settings_dirs, (list, tuple)):
        raise TypeError("settings_dirs must be a list or tuple of directory paths")
    result = []
    for dir_path in settings_dirs:
        if not isinstance(dir_path, str):
            raise TypeError("Each directory path must be a string")
        if not os.path.isdir(dir_path):
            # Skip non-existent or non-directory paths
            continue
        try:
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if not os.path.isfile(full_path):
                    continue
                if spec_option is None:
                    result.append(full_path)
                elif isinstance(spec_option, str):
                    if fnmatch.fnmatch(entry, spec_option):
                        result.append(full_path)
                elif callable(spec_option):
                    try:
                        if spec_option(entry):
                            result.append(full_path)
                    except Exception:
                        # If the filter callable raises, ignore this file
                        pass
                else:
                    raise TypeError("spec_option must be None, a string pattern, or a callable")
        except OSError:
            # Skip directories that cannot be accessed
            continue
    return result

