def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    try:
        # Retrieve the spec definition
        spec = getattr(self, "spec", None)
        if spec is None:
            raise AttributeError("Missing 'spec' attribute on the instance.")
        if not isinstance(spec, dict):
            raise TypeError(f"'spec' must be a dict, got {type(spec).__name__}.")

        # Retrieve any pre‑supplied arguments
        provided = getattr(self, "args", {})
        if provided is None:
            provided = {}
        if not isinstance(provided, dict):
            raise TypeError(f"'args' must be a dict, got {type(provided).__name__}.")

        resolved = {}
        for key, spec_val in spec.items():
            # Prefer a supplied value over the spec default
            if key in provided:
                resolved[key] = provided[key]
                continue

            # If the spec entry is a mapping with a 'default' key, use that
            if isinstance(spec_val, dict) and "default" in spec_val:
                resolved[key] = spec_val["default"]
            else:
                # Otherwise, treat the spec value itself as the default
                resolved[key] = spec_val

        return resolved
    except Exception as exc:
        raise RuntimeError(f"Failed to resolve spec defaults: {exc}") from exc

