def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    if args is None:
        args = {}
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")
    required = []
    for spec in options_spec:
        if not isinstance(spec, dict):
            continue
        if 'required_when' not in spec:
            continue
        cond = spec['required_when']
        try:
            if callable(cond):
                match = cond(args)
            elif isinstance(cond, str):
                # Evaluate the condition string with args as local variables
                match = eval(cond, {}, args)
            else:
                # Treat any other truthy value as a condition
                match = bool(cond)
        except Exception as exc:
            raise ValueError(
                f"Error evaluating 'required_when' for option '{spec.get('name', '<unknown>')}' "
                f"in command '{command_name}': {exc}"
            ) from exc
        if match:
            name = spec.get('name')
            if name:
                required.append(name)
    return required

