def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    :raises TypeError: If args is not a mapping or if an argument value is not a string.
    :raises ValueError: If an argument value exceeds its specified maximum length.
    :return: True if all arguments satisfy the length constraints.
    """
    # Ensure args is a mapping (dict-like)
    if args is None:
        args = {}
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")

    # Retrieve the mapping of argument names to maximum lengths
    max_lengths = getattr(self, "max_lengths", None)
    if max_lengths is None:
        raise AttributeError("The instance does not define 'max_lengths' attribute for length validation.")

    for key, value in args.items():
        # Skip None values (treated as empty)
        if value is None:
            continue

        # Only string values are subject to length checks
        if not isinstance(value, str):
            raise TypeError(f"Argument '{key}' must be a string, got {type(value).__name__}")

        # Determine the maximum allowed length for this argument
        max_len = max_lengths.get(key)
        if max_len is None:
            # No length constraint defined for this argument; skip check
            continue

        if not isinstance(max_len, int) or max_len < 0:
            raise ValueError(f"Maximum length for argument '{key}' must be a non-negative integer, got {max_len}")

        if len(value) > max_len:
            raise ValueError(
                f"Argument '{key}' length {len(value)} exceeds maximum allowed {max_len}"
            )

    return True

