    :param args: The received arguments.
    :raises TypeError: If ``args`` is not a mapping or Namespace.
    :raises ValueError: If a value is not among the allowed choices.
    """
    # Accept a dict or argparse.Namespace
    if not isinstance(args, dict):
        try:
            args = vars(args)
        except Exception:
            raise TypeError("args must be a dict or an argparse.Namespace")

    # Determine the mapping of argument names to allowed choices.
    # Prefer an attribute named `_choices`, fall back to `choices`.
    choices_map = getattr(self, "_choices", None)
    if choices_map is None:
        choices_map = getattr(self, "choices", None)

    # If no choices mapping is defined, nothing to validate.
    if not isinstance(choices_map, dict):
        return

    for arg_name, value in args.items():
        # Skip arguments that have no defined choices.
        if arg_name not in choices_map:
            continue

        allowed = choices_map[arg_name]
        if allowed is None:
            continue

        # Normalize allowed to a set for efficient membership checks.
        try:
            allowed_set = set(allowed)
        except TypeError:
            # If allowed is not iterable (e.g., a single value), treat it as a set of one.
            allowed_set = {allowed}

        # If the value is a collection (list, tuple, set), validate each element.
        if isinstance(value, (list, tuple, set)):
            for v in value:
                if v not in allowed_set:
                    raise ValueError(
                        f"Invalid value for argument '{arg_name}': {v!r}. "
                        f"Allowed choices: {sorted(allowed_set)}"
                    )
        else:
            if value not in allowed_set:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}': {value!r}. "
                    f"Allowed choices: {sorted(allowed_set)}"
                )

